import React from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Autoplay, Pagination } from 'swiper';
import { Link } from 'react-router-dom';
import { FaChevronRight, FaStethoscope, FaFlask, FaHospital, FaMedkit } from 'react-icons/fa';

// Import Swiper styles
import 'swiper/css';
import 'swiper/css/pagination';

const ModernHero = () => {
    const mainSlides = [
        {
            id: 1,
            title: "Healthcare Services",
            subtitle: "Expert Medical Consultations & Lab Tests.",
            cta: "View Services",
            bg: "linear-gradient(90deg, #FDD3EB 0%, #FEECCB 100%)",
            img: "assets/images/home/Service-bnr.png",
        },
        {
            id: 2,
            title: "Healthcare Centres",
            subtitle: "Find Nearby Healthcare Centres.",
            cta: "Explore Centres",
            bg: "linear-gradient(90deg, #FDD3EB 0%, #FEECCB 100%)",
            img: "assets/images/home/Centre-bnr.png",
        }
    ];

    const quickLinks = [
        {
            id: 1,
            title: "Healthcare Services",
            subtitle: "View All",
            icon: <FaStethoscope />,
            bgColor: "#f0fdf4",
            iconColor: "#166534",
            textColor: "#15803d",
            path: "/all-service"
        },
        {
            id: 2,
            title: "Healthcare Packages",
            subtitle: "Book Now",
            icon: <FaFlask />,
            bgColor: "#fffbeb",
            iconColor: "#92400e",
            textColor: "#b45309",
            path: "/all-package"
        },
        {
            id: 3,
            title: "Healthcare Centres",
            subtitle: "Find Nearby",
            icon: <FaHospital />,
            bgColor: "#fdf2f8",
            iconColor: "#9d174d",
            textColor: "#be185d",
            path: "/centers"
        },
        {
            id: 4,
            title: "Medical Solutions",
            subtitle: "Explore Store",
            icon: <FaMedkit />,
            bgColor: "#fff7ed",
            iconColor: "#9a3412",
            textColor: "#c2410c",
            path: "#!"
        }
    ];

    return (
        <section className="modern-hero-section pt-1 pb-2">
            <div className="container container-two">
                {/* Upper Hero Area */}
                <div className="row g-3 mb-4">
                    <div className="col-lg-12">
                        <Swiper
                            modules={[Autoplay, Pagination]}
                            pagination={{ clickable: true }}
                            navigation={false}
                            autoplay={{ delay: 2500 }}
                            loop={true}
                            className="main-hero-swiper rounded-4 overflow-hidden shadow-sm"
                            style={{ height: '230px' }}
                        >
                            {mainSlides.map(slide => (
                                <SwiperSlide key={slide.id}>
                                    <div
                                        className="hero-slide h-100 d-flex align-items-center position-relative overflow-hidden px-4 px-md-5"
                                        style={{ background: slide.bg }}
                                    >
                                        <div className="content-side z-index-2" style={{ maxWidth: '60%', position: 'relative' }}>
                                            <h3 className="fw-bold mb-1" style={{ fontSize: '28px', color: '#0f172a' }}>{slide.title}</h3>
                                            <p className="fs-6 mb-3" style={{ color: '#475569' }}>{slide.subtitle}</p>
                                            <Link to={slide.id === 1 ? "/all-service" : "/centers"} className="btn btn-dark px-4 py-2 fw-semibold" style={{ borderRadius: '8px', backgroundColor: '#0f172a', border: 'none' }}>
                                                {slide.cta}
                                            </Link>
                                        </div>
                                        <div className="image-side position-absolute bottom-0 h-100" style={{ right: '0', width: '45%', zIndex: 1 }}>
                                            <img
                                                src={slide.img}
                                                alt={slide.title}
                                                className="h-100 w-100"
                                                style={{
                                                    objectFit: 'contain',
                                                    objectPosition: 'right bottom',
                                                }}
                                            />
                                        </div>
                                        {/* Seamless Blend Overlay */}
                                        <div
                                            className="position-absolute top-0 start-0 w-100 h-100 z-index-1"
                                            style={{
                                                background: `linear-gradient(90deg, ${slide.bg.split(',')[1].split(' ')[1]} 30%, transparent 100%)`,
                                                pointerEvents: 'none'
                                            }}
                                        ></div>
                                    </div>
                                </SwiperSlide>
                            ))}
                        </Swiper>
                    </div>
                </div>

                {/* Quick Action Rows */}
                <div className="row g-2 justify-content-center mt-3">
                    {quickLinks.map(link => (
                        <div key={link.id} className="col-6 col-md-3">
                            <Link to={link.path} className="text-decoration-none" style={{ display: 'block' }}>
                                <div
                                    className="quick-card py-3 px-3 rounded-4 h-100 d-flex align-items-center justify-content-between transition-all shadow-sm-hover"
                                    style={{ backgroundColor: link.bgColor, border: '1px solid rgba(0,0,0,0.02)' }}
                                >
                                    <div className="d-flex align-items-center gap-1">
                                        <div className="icon-box-modern fs-2" style={{ color: link.iconColor }}>{link.icon}</div>
                                        <div>
                                            <h6 className="mb-0 fw-bold title-text" style={{ fontSize: '16px', color: '#111827' }}>{link.title}</h6>
                                            <span className="fw-bold" style={{ fontSize: '12px', color: link.textColor, letterSpacing: '0.8px' }}>{link.subtitle}</span>
                                        </div>
                                    </div>
                                    <FaChevronRight className="text-muted" style={{ fontSize: '14px', opacity: 0.5 }} />
                                </div>
                            </Link>
                        </div>
                    ))}
                </div>
            </div>

            <style>{`
                .main-hero-swiper .swiper-pagination-bullet-active {
                    background: #0f172a !important;
                }
                .quick-card:hover {
                    box-shadow: 0 8px 20px rgba(0,0,0,0.08);
                    transform: translateY(-3px);
                }
                .fw-bold { font-weight: 700; }
                .fw-semibold { font-weight: 600; }
                .z-index-2 { z-index: 2; }
                .icon-box-modern {
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    width: 40px;
                    height: 40px;
                }

                .main-hero-swiper .swiper-pagination {
                    bottom: 6px !important;
                }
                @media (max-width: 768px) {
                    .main-hero-swiper { height: 215px !important; }
                    .hero-slide h3 { font-size: 22px !important; }
                    .hero-slide p { font-size: 14px !important; }
                    .image-side { width: 40% !important; }
                    .content-side { max-width: 80% !important; }
                }

                @media (max-width: 500px) {
                    .main-hero-swiper { height: 195px !important; }
                    .hero-slide { padding: 16px 16px 28px 16px !important; }
                    .hero-slide h3 { font-size: 17px !important; margin-bottom: 3px !important; }
                    .hero-slide p { font-size: 11.5px !important; margin-bottom: 8px !important; }
                    .image-side { width: 45% !important; right: -10px !important; }
                    .content-side { max-width: 85% !important; }
                    .content-side .btn { padding: 5px 12px !important; font-size: 12px !important; }
                    
                    .quick-card {
                        padding: 0.5rem !important;
                    }
                    .quick-card h6 {
                        font-size: 12px !important;
                        line-height: 1.2 !important;
                    }
                    .quick-card span {
                        font-size: 9px !important;
                        display: block !important;
                    }
                    .icon-box-modern {
                        width: 28px !important;
                        height: 28px !important;
                        font-size: 1.1rem !important;
                    }
                    .quick-card .text-muted {
                        display: none !important; /* Hide chevron on very small screens to save space */
                    }
                }
            `}</style>
        </section>
    );
};

export default ModernHero;
